// Task2同代正式输入风险驱动；只走原玩家任务与钱货入口，不重造或快进政治占领。
#define HANMO_TASK_TAKEOVER_JOURNEY_LIBRARY
#include "task_takeover_world_journey.cpp"
namespace {
// 只消费本次真实静态任务的付款事实，不把动态合同或别人的付款当作该任务结果。
const TaskStaticPaymentSource& terminal_static_payment(const WorldBundle& world,const StableId& id){
    check(world.tasks.takeover_execution&&world.tasks.takeover_execution->version==2,"explicit Task2 section");
    const TaskStaticPaymentSource* result=nullptr;for(const auto& row:world.tasks.takeover_execution->static_payments.rows())if(row.second.task_id==id&&row.second.stage!=TaskStaticPaymentStage::acceptance){check(!result,"duplicate static terminal receipt");result=&row.second;}check(result!=nullptr,"actual static terminal receipt");return *result;
}
// 新显式货物作者沿同一次真实Task流程检查，不给旧Task2银行升级或补造receipt。
void check_static_asset_receipt(const WorldBundle& world,const StableId& task_id,const StableId& stage){
    if(!world.catalog->task_static_assets_enabled)return;
    check(world.tasks.static_assets&&world.tasks.static_assets->receipts.size()==1,"explicit original static asset segment contains one actual terminal source");const auto& receipt=world.tasks.static_assets->receipts.rows().front().second;
    check(receipt.task_id==task_id&&receipt.stage==stage&&receipt.legs.size()==1&&receipt.legs[0].item_id=="qingxi::item.grain"&&receipt.legs[0].quantity==1&&receipt.retained_task_goods.empty(),"same original purchased grain batch really transferred with no retained Task goods");
    check(receipt.legs[0].source_owner.kind==Owner::Kind::task&&receipt.legs[0].source_owner.id==task_id&&receipt.to_container_owner.kind==Owner::Kind::organization&&receipt.to_container_owner.id=="qingxi::org.south","original Task property and original public recipient unchanged");
    const auto& payment=terminal_static_payment(world,task_id);check(receipt.tick==payment.tick&&receipt.source_action_id==payment.source_action_id,"actual asset and original Task2 payment share source tick and action");
}
// 单字段坏档只动自然终态副本；原始bank仍保留，冷门必须拒绝Owner或取消tick伪造。
void reject_static_asset_sources(const V& catalog,const std::shared_ptr<const PreparedCatalog>& prepared,const Bytes& bank,const StableId& task_id,const fs::path& out){
    if(!prepared->task_static_assets_enabled)return;
    for(const auto* field:{"owner","tick"}){
        WorldBundle changed(prepared,must(decode_world_checkpoint(bank,*prepared),"original asset source bank"));must(changed.validate(),"actual asset baseline");auto& source=changed.tasks.static_assets->receipts.rows().front().second;const auto receipt=source.fact_id;
        if(StableId(field)=="owner")source.to_container_owner.id="qingxi::org.north";
        else{check(source.tick>changed.tasks.tasks.find(task_id)->accepted_tick,"natural cancellation is after original acceptance");--source.tick;}
        const auto corrupted=must(encode_world_checkpoint(changed),"encode single asset source mutation");auto session=create_resident_replay_session();const auto result=session->initialize_checkpoint(catalog,corrupted);const StableId expected=StableId(field)=="owner"?"InvalidTaskStaticAssetContainers":"TaskStaticAssetCashSourceMismatch";
        check(!result.ok&&result.error.original.code==expected,"precise asset cold rejection: "+result.error.original.code);write(out/(StableId("bad-asset-")+field+".json"),boundary::obj({{"code",V{result.error.original.code}},{"fact_id",V{receipt}}}));
    }
}
// 原银行仅测试副本改变退款腿；完整Session冷读必须拒绝，原件保持不可变。
void reject_static_route(const V& catalog,const std::shared_ptr<const PreparedCatalog>& prepared,const Bytes& bank,const StableId& task_id,const fs::path& out){
    WorldBundle changed(prepared,must(decode_world_checkpoint(bank,*prepared),"original static bank"));must(changed.validate(),"valid static risk baseline");const auto id=terminal_static_payment(changed,task_id).fact_id;auto* row=changed.tasks.takeover_execution->static_payments.find(id);check(row->stage==TaskStaticPaymentStage::cancellation&&!row->legs.empty(),"nonzero natural cancellation source");row->legs.front().to_wallet_id=changed.common.actor("qingxi::actor.player")->wallet_id;auto corrupted=must(encode_world_checkpoint(changed),"encode static bad route");auto session=create_resident_replay_session();const auto restored=session->initialize_checkpoint(catalog,corrupted);check(!restored.ok&&restored.error.original.code=="TaskStaticPaymentLegMismatch","bad static route rejects at named cold gate: "+restored.error.original.code);write(out/"bad-route.json",boundary::obj({{"code",V{restored.error.original.code}},{"fact_id",V{id}}}));
}
// 用同一自然取消定位最后settlement ID；真实玩家/NPC边界失败均不得发布Task2现金或sidecar。
void late_static_settlement(const V& catalog,const std::shared_ptr<const PreparedCatalog>& prepared,const Bytes& before,const V& params,const V& context,Integer settlement,const StableId& task_id,const fs::path& out){
    const auto original=must(decode_world_checkpoint(before,*prepared),"natural static pre-cancel source");check(settlement>=original.common.next_instance_id,"natural static settlement sequence");const auto offset=settlement-original.common.next_instance_id;
    const auto seed=[&](){auto copy=original;copy.common.next_instance_id=std::numeric_limits<Integer>::max()-offset;return copy;};ResidentWorld world;must(world.install(prepared,seed()),"install exact static risk clone");const auto command=envelope(world,context,"cancel_task",params);const auto unchanged=must(world.checkpoint(),"before static late failure");must(world.preview(command),"real static late cancel preview");const auto failed=world.submit(command);check(!failed.ok&&failed.error.original.code=="InstanceIdOverflow"&&unchanged==must(world.checkpoint(),"after static late failure"),"real static World rolls back late ID");
    WorldBundle direct(prepared,seed());must(direct.validate(),"static direct candidate");const auto operation=must(prepare_command(direct,command.actor_id,*command.payload),"actual static cancel operation");const auto applied=apply_command(direct,command.actor_id,*operation->operation);check(!applied.ok&&applied.error.original.code=="InstanceIdOverflow"&&terminal_static_payment(direct,task_id).stage==TaskStaticPaymentStage::cancellation,"actual static receipt precedes final failure");if(prepared->task_static_assets_enabled)check_static_asset_receipt(direct,task_id,"cancellation_return");
    WorldBundle npc(prepared,seed());const auto npc_before=must(encode_world_checkpoint(npc),"NPC static before");bool accepted=true;must(try_npc_command(npc,command.actor_id,*command.payload,accepted),"actual NPC static transaction");check(!accepted&&npc_before==must(encode_world_checkpoint(npc),"NPC static after"),"NPC static rollback keeps all World bytes");write(out/"late-settlement.json",boundary::obj({{"whole_world_unchanged",V{true}},{"receipt_before_failure",V{true}},{"npc_whole_world_unchanged",V{true}},{"offset",V{offset}}}));
}
// 接、买、交均用当前页面原参数；取消分支复用同一自然购货银行，不加钱或注入任务。
void static_public_live(const V& catalog,const V& request,const fs::path& out){
    check(text(request,"scenario_id")=="task_handover::scenario.south_static_responsibility","explicit static Task2 author required");auto world=create_resident_replay_session();must(world->initialize_native(catalog,request),"formal static Task2 initialize");cold_exact(catalog,save_bank(*world,out/"initial.hmcb"));task_journey_travel(*world,"qingxi::settlement.south");meet_task_role(*world,"task_handover::role.supply");
    submit(*world,"dialogue_next",V{V::Dict{}});submit(*world,"dialogue_choose",boundary::obj({{"option_id",V{"ask"}}}));
    submit(*world,"accept_offer",action_params(*world,"interaction_tasks","accept_offer"));finish_task_journey_action(*world);const auto active=save_bank(*world,out/"active.hmcb");cold_exact(catalog,active);auto prepared=prepare_from_bank(catalog,active);auto state=inspect(*world,prepared);const auto* task=task_for(state.tasks,"qingxi::actor.player","task_handover::offer.static_grain");check(task&&!task->contract_id&&task->status=="active","genuine static Task accepted");const auto task_id=task->id,escrow=task->budget_wallet_id;check(state.tasks.takeover_execution&&state.tasks.takeover_execution->version==2&&state.tasks.takeover_execution->static_payments.size()==1&&state.common.wallet(escrow)->balance==24,"actual Task2 initial budget receipt");
    submit(*world,"end_interaction",V{V::Dict{}});meet_task_role(*world,"task_handover::role.clerk_trade");submit(*world,"dialogue_next",V{V::Dict{}});submit(*world,"dialogue_confirm",V{V::Dict{}});const auto trade=query(*world,"trade_view",boundary::obj({{"shop_id",V{"task_handover::shop.civil_grain"}},{"provider_actor_id",V{"task_handover::actor.supply_clerk"}}}));bool payer=false;for(const auto& row:boundary::array(field(trade,"task_payers"),"payers"))if(text(row,"offer_id")==task->offer_id&&text(row,"wallet_id")==escrow)payer=true;check(payer,"static escrow appears in real trade page");
    submit(*world,"trade",boundary::obj({{"shop_id",V{"task_handover::shop.civil_grain"}},{"item_id",V{"qingxi::item.grain"}},{"quantity",V{Integer{1}}},{"side",V{"buy"}},{"payer_wallet_id",V{escrow}},{"context",boundary::obj({{"place_id",V{"qingxi::place.south.gate"}},{"provider_actor_id",V{"task_handover::actor.supply_clerk"}},{"role_id",V{"task_handover::role.clerk_trade"}}})}}));finish_task_journey_action(*world);submit(*world,"close_trade",V{V::Dict{}});submit(*world,"end_interaction",V{V::Dict{}});meet_task_role(*world,"task_handover::role.supply");const auto purchased=save_bank(*world,out/"purchased.hmcb");cold_exact(catalog,purchased);
    auto before=inspect(*world,prepared);const auto remaining=before.common.wallet(escrow)->balance;check(remaining==4,"original static purchase spent twenty");const auto actor_wallet=before.common.actor("qingxi::actor.player")->wallet_id;const auto cancel=action_params(*world,"interaction_tasks","cancel_task",task_id),context=query(*world,"command_context");
    submit(*world,"report_offer",action_params(*world,"interaction_tasks","report_offer",task_id));finish_task_journey_action(*world);auto complete=inspect(*world,prepared);const auto& paid=terminal_static_payment(complete,task_id);check(paid.stage==TaskStaticPaymentStage::report_success&&paid.legs.size()==2&&paid.legs[0].purpose==TaskStaticPaymentPurpose::unused_budget_award&&paid.legs[0].amount==4&&paid.legs[1].purpose==TaskStaticPaymentPurpose::reward_payment&&paid.legs[1].amount==8,"original static success awards unused four and reward eight separately");check(complete.common.wallet(actor_wallet)->balance==before.common.wallet(actor_wallet)->balance+12&&complete.common.wallet(escrow)->balance==0,"actual original actor received static cash");check(complete.common.count("store:qingxi::org.south","qingxi::item.grain",{{Owner::Kind::organization,"qingxi::org.south",{}}}).value==1,"original static beneficiary receives grain");check_static_asset_receipt(complete,task_id,"procurement_delivery");cold_exact(catalog,save_bank(*world,out/"reported.hmcb"));
    auto cancellation=create_resident_replay_session();must(cancellation->initialize_checkpoint(catalog,purchased),"same natural purchased branch");submit(*cancellation,"cancel_task",cancel);auto cancelled=inspect(*cancellation,prepared);check(cancelled.common.tick()==before.common.tick()&&cash_total(cancelled)==cash_total(before)&&cancelled.common.wallet("qingxi::wallet.south.public")->balance==before.common.wallet("qingxi::wallet.south.public")->balance+4&&cancelled.common.wallet(actor_wallet)->balance==before.common.wallet(actor_wallet)->balance,"zero-time cancellation conserves cash and refunds exactly four");const auto cancelled_bank=save_bank(*cancellation,out/"cancelled.hmcb");cold_exact(catalog,cancelled_bank);reject_static_route(catalog,prepared,cancelled_bank,task_id,out);check_static_asset_receipt(cancelled,task_id,"cancellation_return");reject_static_asset_sources(catalog,prepared,cancelled_bank,task_id,out);const auto& settlement=cancelled.tasks.tasks.find(task_id)->settlement_id;late_static_settlement(catalog,prepared,purchased,cancel,context,std::stoll(settlement.substr(settlement.find(':')+1)),task_id,out);
}
}
int main(int argc,char** argv){fs::path out;try{check(argc==4,"usage: task_static_public_world_probe PREPARED REQUEST FRESH_OUTPUT");out=argv[3];check(!fs::exists(out),"fresh output required");fs::create_directories(out);static_public_live(read(argv[1]),read(argv[2]),out);write(out/"result.json",boundary::obj({{"ok",V{true}},{"checks",V{checks}},{"trace",V{trace}},{"scope",V{"normal Task2 cash/cold/player-NPC transaction gates; political capture and GUI separate"}}}));return 0;}catch(const std::exception& error){if(!out.empty()&&fs::exists(out))write(out/"failure.json",boundary::obj({{"ok",V{false}},{"error",V{StableId(error.what())}},{"trace",V{trace}}}));std::cerr<<error.what()<<'\n';return 1;}}
